-- ---------- Named checks (mirrored in src/server/fees.ts and catalogue.ts) ----------
alter table app.fee_category add constraint fee_category_code_check check (code ~ '^[!-~]+( [!-~]+)*$' and code = upper(code) and length(code) <= 30);
alter table app.fee_category add constraint fee_category_name_check check (name = btrim(name) and char_length(name) between 1 and 200);
alter table app.fee_type add constraint fee_type_code_check check (code ~ '^[!-~]+( [!-~]+)*$' and code = upper(code) and length(code) <= 30);
alter table app.fee_type add constraint fee_type_name_check check (name = btrim(name) and char_length(name) between 1 and 200);
alter table app.fee_type add constraint fee_type_hsn_sac_check check (hsn_sac ~ '^[0-9]{4,8}$');
alter table app.fee_type add constraint fee_type_gst_rate_check check (gst_rate between 0 and 100); -- the allowed list is an app parameter (PMC)
alter table app.fee_type add constraint fee_type_sort_order_check check (sort_order between 0 and 9999);
alter table app.fee_caption add constraint fee_caption_name_check check (name = btrim(name) and char_length(name) between 1 and 200);
alter table app.fee_caption add constraint fee_caption_sort_order_check check (sort_order between 0 and 9999);
alter table app.fee_plan add constraint fee_plan_key_check check (num_nonnulls(centre_class_id, centre_id) = 1);
alter table app.fee_plan add constraint fee_plan_status_check check (status in ('DRAFT', 'PUBLISHED'));
alter table app.fee_plan add constraint fee_plan_published_check check ((status = 'PUBLISHED') = (published_at is not null and published_by is not null));
alter table app.fee_plan add constraint fee_plan_version_check check (version >= 1);
alter table app.fee_plan add constraint fee_plan_currency_check check (currency ~ '^[A-Z]{3}$');
alter table app.fee_plan add constraint fee_plan_class_currency_check check (centre_class_id is null or currency = 'INR'); -- DD-7
alter table app.fee_plan_line add constraint fee_plan_line_amount_check check (amount >= 0);
comment on column app.fee_plan_line.amount is 'GST-inclusive (fee-structure DD-1); F3 copies the rate and HSN/SAC onto each allocation at receipt';

-- ---------- Guards: rules only, so they bind every role (unlike the permission part of 0020/0021). The driver drops
-- error.constraint, so each message carries its name. Nested ifs: plpgsql does not short-circuit AND. ----------
create function app.fee_plan_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare k text;
begin
  if tg_op = 'INSERT' then
    -- one DRAFT per key (R2): the key built as fees.ts builds it, locked, then checked
    k := 'fee-plan:' || new.academic_year || ':' || new.course_id || ':K' || coalesce(new.centre_class_id::text, '') || 'C' || coalesce(new.centre_id::text, '');
    perform pg_advisory_xact_lock(hashtext(k));
    if new.status <> 'DRAFT' or new.published_at is not null or new.published_by is not null then
      raise exception 'a new plan is a draft: constraint "fee_plan_guard"' using errcode = '23514', constraint = 'fee_plan_guard';
    end if;
    if exists (select 1 from app.fee_plan p where p.status = 'DRAFT' and p.academic_year = new.academic_year and p.course_id = new.course_id
               and p.centre_class_id is not distinct from new.centre_class_id and p.centre_id is not distinct from new.centre_id) then
      raise exception 'one draft per key: constraint "fee_plan_draft_guard"' using errcode = '23514', constraint = 'fee_plan_draft_guard';
    end if;
    return new;
  end if;
  if old.status <> 'DRAFT' then
    raise exception 'a published plan never changes: constraint "fee_plan_guard"' using errcode = '23514', constraint = 'fee_plan_guard';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  -- the only update: DRAFT -> PUBLISHED, every other column unchanged; who and when stamped here
  if new.status <> 'PUBLISHED' or (to_jsonb(new) - 'status' - 'published_at' - 'published_by') is distinct from (to_jsonb(old) - 'status' - 'published_at' - 'published_by') then
    raise exception 'a draft is only published: constraint "fee_plan_guard"' using errcode = '23514', constraint = 'fee_plan_guard';
  end if;
  if not exists (select 1 from app.fee_plan_line l where l.plan_id = new.id) then
    raise exception 'a plan needs lines: constraint "fee_plan_empty_guard"' using errcode = '23514', constraint = 'fee_plan_empty_guard';
  end if;
  new.published_at := now();
  new.published_by := coalesce(app.session_user_id(), new.published_by);
  return new;
end $$;
create trigger fee_plan_guard before insert or update or delete on app.fee_plan for each row execute function app.fee_plan_guard();

create function app.fee_plan_line_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare st text;
begin
  -- for share (D1): a concurrent publish holds for update; after it commits this re-reads PUBLISHED and refuses
  select p.status into st from app.fee_plan p where p.id = case when tg_op = 'DELETE' then old.plan_id else new.plan_id end for share;
  if st is null or st <> 'DRAFT' then
    raise exception 'only a draft plan''s lines change: constraint "fee_plan_line_guard"' using errcode = '23514', constraint = 'fee_plan_line_guard';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
create trigger fee_plan_line_guard before insert or update or delete on app.fee_plan_line for each row execute function app.fee_plan_line_guard();

create function app.fee_caption_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
begin
  if exists (select 1 from app.fee_plan_line l join app.fee_plan p on p.id = l.plan_id where l.caption_id = new.id and p.status = 'PUBLISHED') then
    raise exception 'a due date used by a published plan never changes: constraint "fee_caption_guard"' using errcode = '23514', constraint = 'fee_caption_guard';
  end if;
  return new;
end $$;
create trigger fee_caption_guard before update of due_on on app.fee_caption for each row
  when (new.due_on is distinct from old.due_on) execute function app.fee_caption_guard();

-- ---------- RLS: everyone reads masters and published plans; fee.setup (ALL scope) writes; drafts are fee.setup's ----------
do $$
declare t text;
begin
  foreach t in array array['fee_category', 'fee_type', 'fee_caption'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy setup_select on app.%I for select using (true)', t);
    execute format('create policy setup_insert on app.%I for insert with check ((select app.has_permission(''fee.setup'', null)))', t);
    execute format('create policy setup_update on app.%I for update using ((select app.has_permission(''fee.setup'', null))) with check ((select app.has_permission(''fee.setup'', null)))', t);
  end loop;
end $$;
alter table app.fee_plan enable row level security;
alter table app.fee_plan force row level security;
create policy fee_plan_select on app.fee_plan for select using (status = 'PUBLISHED' or (select app.has_permission('fee.setup', null)));
create policy fee_plan_insert on app.fee_plan for insert with check ((select app.has_permission('fee.setup', null)));
create policy fee_plan_update on app.fee_plan for update using ((select app.has_permission('fee.setup', null))) with check ((select app.has_permission('fee.setup', null)));
create policy fee_plan_delete on app.fee_plan for delete using ((select app.has_permission('fee.setup', null)) and status = 'DRAFT');
alter table app.fee_plan_line enable row level security;
alter table app.fee_plan_line force row level security;
create policy fee_plan_line_select on app.fee_plan_line for select using (exists (select 1 from app.fee_plan p where p.id = plan_id));
create policy fee_plan_line_insert on app.fee_plan_line for insert with check ((select app.has_permission('fee.setup', null)));
create policy fee_plan_line_update on app.fee_plan_line for update using ((select app.has_permission('fee.setup', null))) with check ((select app.has_permission('fee.setup', null)));
create policy fee_plan_line_delete on app.fee_plan_line for delete using ((select app.has_permission('fee.setup', null)));

-- ---------- Permission; the system administrator holds every permission (0013) ----------
insert into app.permission (key, description, sensitive) values
  ('fee.setup', 'Maintain fee categories, fee types, instalments and fee plans', true)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'fee.setup' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grants (codes, keys and years never change; status changes only through the guard) ----------
grant select on app.fee_category, app.fee_type, app.fee_caption, app.fee_plan, app.fee_plan_line to gems_app;
grant usage on sequence app.fee_category_id_seq, app.fee_type_id_seq, app.fee_caption_id_seq, app.fee_plan_id_seq, app.fee_plan_line_id_seq to gems_app;
grant insert (code, name), update (name, active) on app.fee_category to gems_app;
grant insert (code, name, category_id, sort_order, hsn_sac, gst_rate), update (name, sort_order, hsn_sac, gst_rate, active) on app.fee_type to gems_app;
grant insert (academic_year, name, due_on, sort_order), update (name, due_on, sort_order, active) on app.fee_caption to gems_app;
grant insert (id, academic_year, course_id, centre_class_id, centre_id, version), update (status), delete on app.fee_plan to gems_app;
grant insert (plan_id, academic_year, fee_type_id, caption_id, amount), update (amount), delete on app.fee_plan_line to gems_app;
